"IR-9(2)": {"statement":[{"prose":"Provide information spillage response training [Assignment: organization-defined frequency]."}],"discussion":["Organizations establish requirements for responding to information spillage incidents in incident response plans. Incident response training on a regular basis helps to ensure that organizational personnel understand their individual responsibilities and what specific actions to take when spillage incidents occur."],"params":[{"id":"IR-09(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to provide information spillage response training is defined"}],"related":["AT-2","AT-3","CP-3","IR-2"],"objectives":[{"id":"ir-9.2_obj","label":"IR-09(02)","prose":"information spillage response training is provided [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing information spillage response training","information spillage response training curriculum","information spillage response training materials","incident response plan","system security plan","information spillage response training records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident response training responsibilities","organizational personnel with information security responsibilities"]}],"references":[]},
"IR-9(3)": {"statement":[{"prose":"Implement the following procedures to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions: [Assignment: organization-defined procedures]."}],"discussion":["Corrective actions for systems contaminated due to information spillages may be time-consuming. Personnel may not have access to the contaminated systems while corrective actions are being taken, which may potentially affect their ability to conduct organizational business."],"params":[{"id":"IR-09(03)_ODP","kind":"Assignment","value":"[Assignment: organization-defined procedures]","guideline":"procedures to be implemented to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions are defined"}],"related":[],"objectives":[{"id":"ir-9.3_obj","label":"IR-09(03)","prose":"[Assignment: organization-defined procedures] are implemented to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions."}],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident response","procedures addressing information spillage","incident response plan","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident response responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for post-spill operations"]}],"references":[]},
"IR-9(4)": {"statement":[{"prose":"Employ the following controls for personnel exposed to information not within assigned access authorizations: [Assignment: organization-defined controls]."}],"discussion":["Controls include ensuring that personnel who are exposed to spilled information are made aware of the laws, executive orders, directives, regulations, policies, standards, and guidelines regarding the information and the restrictions imposed based on exposure to such information."],"params":[{"id":"IR-09(04)_ODP","kind":"Assignment","value":"[Assignment: organization-defined controls]","guideline":"controls employed for personnel exposed to information not within assigned access authorizations are defined"}],"related":[],"objectives":[{"id":"ir-9.4_obj","label":"IR-09(04)","prose":"[Assignment: organization-defined controls] are employed for personnel exposed to information not within assigned access authorizations."}],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident response","procedures addressing information spillage","incident response plan","system security plan","security safeguards regarding information spillage/exposure to unauthorized personnel","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident response responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for dealing with information exposed to unauthorized personnel","mechanisms supporting and/or implementing safeguards for personnel exposed to information not within assigned access authorizations"]}],"references":[]},
